// The swap helper is the single place where both mappings change together
void swapNodes(int i, int j) {
    std::swap(heap[i], heap[j]);   // index -> identity direction updates automatically
    position[heap[i]] = i;         // identity -> index direction updated explicitly
    position[heap[j]] = j;
}

class IndexedMinHeap {
    vector<int> heap;        // heap[i]        = identity stored at heap index i
    vector<int> position;    // position[id]   = current heap index of identity id, or -1
    vector<long long> dist;  // dist[id]       = current priority (key) of identity id
    int size;

public:
    explicit IndexedMinHeap(int n)
        : heap(n), position(n, -1), dist(n, LLONG_MAX), size(0) {}

    bool empty() const { return size == 0; }

    bool contains(int identity) const { return position[identity] != -1; }

    void swapNodes(int i, int j) {
        std::swap(heap[i], heap[j]);
        position[heap[i]] = i;
        position[heap[j]] = j;
    }

    void siftUp(int i) {
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (dist[heap[i]] < dist[heap[parent]]) {
                swapNodes(i, parent);
                i = parent;
            } else {
                break;
            }
        }
    }

    void siftDown(int i) {
        while (true) {
            int left = 2 * i + 1, right = 2 * i + 2, smallest = i;
            if (left < size && dist[heap[left]] < dist[heap[smallest]]) smallest = left;
            if (right < size && dist[heap[right]] < dist[heap[smallest]]) smallest = right;
            if (smallest == i) break;
            swapNodes(i, smallest);
            i = smallest;
        }
    }

    void insert(int identity, long long priority) {
        dist[identity] = priority;
        heap[size] = identity;
        position[identity] = size;
        size++;
        siftUp(size - 1);
    }

    void decreaseKey(int identity, long long newPriority) {
        if (newPriority >= dist[identity]) return; // not an improvement, ignore
        dist[identity] = newPriority;
        siftUp(position[identity]);   // O(1) lookup, then O(log n) sift
    }

    pair<int, long long> extractMin() {
        int minIdentity = heap[0];
        long long minDist = dist[minIdentity];

        size--;
        swapNodes(0, size);          // move the last element to the root
        position[minIdentity] = -1;  // mark this identity as removed

        if (size > 0) siftDown(0);
        return {minIdentity, minDist};
    }
};

vector<long long> dist(n, LLONG_MAX);
IndexedMinHeap pq(n);

dist[src] = 0;
pq.insert(src, 0);

while (!pq.empty()) {
    auto [u, du] = pq.extractMin();

    for (auto& [v, w] : adj[u]) {
        long long candidate = du + w;
        if (candidate < dist[v]) {
            dist[v] = candidate;
            if (pq.contains(v)) {
                pq.decreaseKey(v, candidate);   // node already waiting: fix its priority in place
            } else {
                pq.insert(v, candidate);        // node seen for the first time
            }
        }
    }
}

// Lazy deletion workaround using a plain STL priority_queue
priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
vector<long long> dist(n, LLONG_MAX);
vector<bool> visited(n, false);

dist[src] = 0;
pq.push({0, src});

while (!pq.empty()) {
    auto [d, u] = pq.top(); pq.pop();
    if (visited[u]) continue;      // stale entry left over from an earlier, worse distance
    visited[u] = true;

    for (auto& [v, w] : adj[u]) {
        if (dist[u] + w < dist[v]) {
            dist[v] = dist[u] + w;
            pq.push({dist[v], v});  // push a brand new entry instead of decreaseKey
        }
    }
}
